Text Only<pre><code>claude_desktop_config.json
</code></pre> - ​作用​： Claude ​桌面版​的​主​配置文件​，​最​重要​的​配置​之一​。 - ​包含​内容​：     - MCP (Model Context Protocol) ​服务器​配置​     - ​自定义​工具​和​插件​     - ​快捷键​设置​     - ​工作​目录​偏好​ <ul> <li>​例子​： ​如果​你​配置​了​文件系统​访问​或​其他​ MCP ​服务器​，​配置​就​存在​这里​：     Text Only<pre><code>{
  "mcpServers": {
    "filesystem": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-filesystem", "/path/to/allowed"]
    }
  }
}
</code></pre></li> <li>​能否​清理​： ​删​了​会​丢失​所有​自定义​配置​</li> </ul> Text Only<pre><code>config.json
</code></pre> - ​作用​： ​运行​时​配置​，​记录​应用​的​当前​状态​和​运行​参数​。 <ul> <li> <p>​包含​内容​：</p> <ul> <li>​当前​选择​的​模型​</li> <li>UI ​设置​</li> <li>​功能​开关​状态​</li> </ul> </li> <li> <p>​能否​清理​： ​删​了​可能​导致​应用​设置​重置​</p> </li> </ul> <p></p>Text Only<pre><code>Preferences
</code></pre> - ​作用​： ​用户​偏好​设置​的​持久​化​存储​。 - ​包含​内容​：     - ​界面​主题​     - ​字体大小​     - ​通知​设置​     - ​是否​启用​某些​功能​<p></p> <ul> <li>​能否​清理​： ​删​了​会​重置​为​默认设置​</li> </ul>

C++<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;netinet/in.h&gt;

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    const char *response = "Hello from server";

    // 1. ​创建​ TCP Socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) &lt; 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // 2. ​设置​地址​结构​
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY; 
    address.sin_port = htons(PORT);       

    // 3. ​绑定​Socket
    if (bind(server_fd, (struct sockaddr *)&amp;address, sizeof(address)) &lt; 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // 4. ​监听​连接​，​最大​等待​队列​长度​3
    if (listen(server_fd, 3) &lt; 0) {
        perror("listen failed");
        exit(EXIT_FAILURE);
    }
    printf("Server listening on port %d...\n", PORT);

    // 5. ​接受​客户端​连接​
    if ((new_socket = accept(server_fd, (struct sockaddr *)&amp;address, (socklen_t*)&amp;addrlen)) &lt; 0) {
        perror("accept failed");
        exit(EXIT_FAILURE);
    }
    printf("Client connected\n");

    // 6. ​读取​客户端​数据​
    read(new_socket, buffer, BUFFER_SIZE);
    printf("Received from client: %s\n", buffer);

    // 7. ​向​客户端​发送​响应​
    send(new_socket, response, strlen(response), 0);
    printf("Response sent\n");

    // 8. ​关闭​连接​
    close(new_socket);
    close(server_fd);
    return 0;
}
</code></pre>

C++<pre><code>while(1) {
    new_socket = accept(server_fd, ...); // ​取出​一个​连接​

    pid_t pid = fork();

    if (pid == 0) {
        // ​子​进程​代码​空间​
        close(server_fd); // ​子​进程​不​需要​监听​套​接字​

        // ​处理​客户端​请求​（​可能​耗时​）
        char buffer[1024];
        read(new_socket, buffer, 1024);
        send(new_socket, "Hello", 5, 0);

        close(new_socket);
        exit(0); // ​子​进程​结束​
    }
    else if (pid &gt; 0) {
        // ​父​进程​代码​空间​
        close(new_socket); // ​父​进程​关闭​已​交给​子​进程​的​连接​描述符​
        // ​继续​ while ​循环​，accept ​下​一个​
    }
    else {
        perror("fork failed");
    }

}
</code></pre> - fork() ​一次​调用​后​，​父​进程​和子​进程​都​会​从​该点​继续执行​。​系统​会​给​父​进程​返回​子​进程​的​进程​号​（​正整数​），​给子​进程​返回​ 0。​通过​ if (pid == 0) ​可以​让子​进程​执行​处理​客户端​请求​的​代码​，​而父​进程​则​回到​ accept() ​继续​监听​新​的​连接​，​从而​实现​并发​处理​。

C++<pre><code>#include &lt;pthread.h&gt;

void *handle_client(void *arg) {
    int new_socket = *(int*)arg;
    free(arg); // ​释放​动态分配​的​内存​

    // ​处理​请求​
    char buffer[1024];
    read(new_socket, buffer, 1024);
    send(new_socket, "Hello", 5, 0);

    close(new_socket);
    pthread_exit(NULL);
}

int main() {
    // ... socket, bind, listen ...

    while(1) {
        int *new_sock_ptr = malloc(sizeof(int)); // ​必须​动态分配​
        *new_sock_ptr = accept(server_fd, ...);

        pthread_t thread_id;
        if (pthread_create(&amp;thread_id, NULL, handle_client, (void*)new_sock_ptr) != 0) {
perror("pthread_create failed");
            free(new_sock_ptr);
        }

        // ​分离​线程​，​避免​僵尸​线程​
        pthread_detach(thread_id);
    }
}
</code></pre> - ​传递​给​线程​的​  new_socket  ​必须​动态分配​（ malloc ），​否则​主线​程​修改​时​，​线程​可能​读​到​错误​值​。 C++<pre><code>// ​错误​示例​：​不要​这样​做​！

while (1) {
    int new_socket = accept(server_fd, ...);
    pthread_create(&amp;tid, NULL, handle_client, &amp;new_socket); // ​传递​局部变量​地址​
}
</code></pre> - ​主线​程​的​ new_socket ​是​一个​局部变量​，​存储​在​主线​程​的​栈​上​。​当​主线​程​循环​到​下​一次​ accept ​时​，​会​复用​同​一块​栈​内存​，​导致​ new_socket ​的​值​被​覆盖​。​而​此时​，​子​线程​可能​还​在​使用​这个​地址​读取​ new_socket ​的​值​，​就​会​读​到​已经​被​主线​程​修改​的​新值​，​而​不是​创建​线程​时​的​旧值​，​从而​引发​错误​。

C++<pre><code>#include &lt;sys/epoll.h&gt;

#define MAX_EVENTS 64

int epfd = epoll_create1(0);
struct epoll_event ev, events[MAX_EVENTS];

// ​将​监听​套​接字​加入​ epoll
ev.events = EPOLLIN;
ev.data.fd = server_fd;
epoll_ctl(epfd, EPOLL_CTL_ADD, server_fd, &amp;ev);

while(1) {
    // ​阻塞​等待​事件​
    int nfds = epoll_wait(epfd, events, MAX_EVENTS, -1);

    for (int i = 0; i &lt; nfds; i++) {
        if (events[i].data.fd == server_fd) {
            // ​新​连接​到来​
            int new_socket；
            while ((new_socket = accept(server_fd, NULL, NULL)) &gt; 0) {
                // ​将​新​连接​也​加入​ epoll ​监听​（​边缘​触发​ ET ​模式​）
                ev.events = EPOLLIN | EPOLLET;
                ev.data.fd = new_socket;
                epoll_ctl(epfd, EPOLL_CTL_ADD, new_socket, &amp;ev);
            }
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // ​正常​情况​：​连接​队列​已空​
            } else {
                perror("accept");
            }
        }
        else {
            // ​已有​连接​有​数据​可​读​
            int sockfd = events[i].data.fd;
            char buffer[1024];
            int n = read(sockfd, buffer, sizeof(buffer));

            if (n &lt;= 0) {
                // ​连接​关闭​或​错误​
                close(sockfd);
                epoll_ctl(epfd, EPOLL_CTL_DEL, sockfd, NULL);
            } else {
                // ​处理​数据​（​如​ echo）
                send(sockfd, buffer, n, 0);
            }
        }
    }
}
</code></pre> - ​多路复用​的​本质​是​“​把​多条​数据流​合并​到​一条​物理​信道​上​传输​，​接收端​再​把​它们​拆开​”，​这样​就​能​用​更​少​的​硬件资源​同时​服务​更​多用户​。​核心​思路​可以​拆成​三步​。​为了​防止​各路​信号​互相​干扰​，​系统​会​给​每路​信号​分配​互不​重叠​的​资源​——​要么​是​不同​的​频率​（FDM）、​不同​的​时间​片​（TDM）、​不同​的​波长​（WDM），​或者​不同​的​空间​路径​（SDM）。     1. ​发端​把​多路​信号​“​打包​”：​把​每个​用户​的​信号​按​某种​规则​（​时间​、​频率​、​波长​等​）​切成​小​片​，​然后​把​这些​小​片​拼成​一条​高速​流​。     2. ​在​一条​线路​上传​：​这​条​线路​可以​是​铜线​、​光纤​或​无线​频段​，​只要​带宽​足够​，​就​能​把​打包​后​的​信号​一起​发出​去​。​收端​把​信号​“​拆包​”     3. ​按​发端​约定​的​规则​，​把​收到​的​高速​流​重新​还原成​原来​的​多路​信号​，​送给​对应​的​用户​。 <ul> <li> <p>​此处​本质​是​让​内核​帮​你​同时​监视​多个​文件​描述符​，​一旦​有​就绪​的​就​立刻​通知​你​，​这样​你​就​可以​用​一个​线程​处理​成百上千​个​连接​，​而​不用​为​每个​连接​都​创建​线程​或​进程​。</p> </li> <li> <p>​核心思想​</p> <ol> <li>​问题​：​传统​方式​中​，​如果​要​同时​处理​多个​客户端​连接​，​通常​需要​为​每个​连接​创建​一个​线程​或​进程​。​当​连接​数很多​时​，​系统资源​消耗​巨大​，​效率​低下​。</li> <li>​解决方案​：​多路复用​技术​允许​一个​线程​同时​监视​多个​文件​描述符​（​如套​接字​），​一旦​某个​文件​描述符​就绪​（​可以​读​或​写​），​就​立即​通知​应用程序​进行​处理​。</li> </ol> </li> <li>​实现​机制​<ol> <li>select：​将​文件​描述符​集合​传递​给​内核​，​内核​轮询​检查​每个​文件​描述符​是否​就绪​。select ​使用​固定​大小​的​位​图来​表示​文件​描述符​集合​，​因此​有​最大​文件​描述符​数量​的​限制​（​通常​是​ 1024）。​每次​调用​ select ​都​需要​将​整个​集合​从​用户​空间​复制到​内核​空间​，​效率​较​低​。</li> <li>poll：​与​ select ​类似​，​但​使用​动态​数组​来​表示​文件​描述符​集合​，​没有​最大​文件​描述符​数量​的​限制​。​同样​需要​将​整个​集合​从​用户​空间​复制到​内核​空间​。</li> <li>epoll（Linux ​特有​）：​使用​事件驱动​的​方式​，​内核​维护​一个​就绪​事件​的​链表​，​只​将​就绪​的​事件​返回​给​应用程序​，​避免​了​轮询​和​复制​整个​集合​的​开销​。epoll ​支持​水平​触发​和​边缘​触发​两种​模式​，​效率​更高​。</li> </ol> </li> <li> <p>​工作​流程​</p> <ol> <li>​注册​：​应用程序​将​需要​监视​的​文件​描述符​及其​感兴趣​的​事件​（​如读​就绪​、​写​就绪​）​注册​到​内核​的​多路复用​器中​。</li> <li>​等待​：​应用程序​调用​多路复用​系统​调用​（​如​ select、poll、epoll_wait），​进入​阻塞状态​，​等待​内核​通知​。</li> <li>​通知​：​内核​监视​所有​注册​的​文件​描述符​，​一旦​有​文件​描述符​就绪​，​就​将​就绪​的​文件​描述符​及其​事件​返回​给​应用程序​。</li> <li>​处理​：​应用程序​根据​返回​的​就绪​事件​，​对​相应​的​文件​描述符​进行​读写操作​，​然后​继续​等待​下​一次​通知​。</li> </ol> </li> <li> <p>​当​一个​监听​ socket（server_fd）​变得​“​可​读​”​时​，​表示​：​有​新​的​客户端​连接​请求​到达​了​！​也就是说​，“​可​读​”​在​这里​不是​指​收到​了​数据​，​而是​“​可以​ accept ​了​”。</p> </li> <li> <p>​因为​ Linux ​把​ ​网络连接​、​文件​、socket ​都​抽象​成​“​文件​描述符​”（file descriptor），​并​统一​用​“​可​读​/​可​写​”​来​表示​事件​。</p> <ol> <li>​普通​文件​：​可​读​ = ​有​数据​可以​读取​。</li> <li>​监听​ socket：​可​读​ = ​有​新​连接​可以​ accept。</li> <li>​已​连接​ socket：​可​读​ = ​客户端​发来​了​数据​。</li> </ol> </li> <li> <p>​每次​调用​ epoll_wait ​时​，​内核​会​把​“​哪些​ socket ​就绪​了​”​写​进​这个​数组​。​旧​内容​会​被​完全​覆盖​。</p> </li> </ul>

C++<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/socket.h&gt;
#include &lt;netinet/in.h&gt;
#include &lt;arpa/inet.h&gt;

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int sock = 0;
    struct sockaddr_in serv_addr;
    char buffer[BUFFER_SIZE] = {0};
    const char *message = "Hello from client";

    // 1. ​创建​ TCP Socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) &lt; 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // 2. ​设置​服务器​地址​
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(PORT);
    if (inet_pton(AF_INET, "127.0.0.1", &amp;serv_addr.sin_addr) &lt;= 0) {
        perror("invalid address");
        exit(EXIT_FAILURE);
    }

    // 3. ​连接​服务器​
    if (connect(sock, (struct sockaddr *)&amp;serv_addr, sizeof(serv_addr)) &lt; 0) {
        perror("connection failed");
        exit(EXIT_FAILURE);
    }

    // 4. ​向​服务器发送​数据​
    send(sock, message, strlen(message), 0);
    printf("Message sent\n");

    // 5. ​读取​服务器​响应​
    read(sock, buffer, BUFFER_SIZE);
    printf("Received from server: %s\n", buffer);

    // 6. ​关闭​连接​
    close(sock);
    return 0;
}
</code></pre>

