C++<pre><code>//.h
class Single
{
public:
    static Single&amp; GetInstance();// ​获取​单​实例​对象​
    void Print();// ​打印​实例​地址​

private:
    Single()= default;// ​禁止​外部​构造​
    ~Single()= default;// ​禁止​外部​析构​
    Single(const Single &amp;single) = delete;// ​禁止​外部​拷贝​构造​
    const Single &amp;operator=(const Single &amp;single) = delete;// ​禁止​外部​赋值​操作​
};

//.cpp
Single&amp; Single::GetInstance()
{
    /**
     * ​局部​静态​特性​的​方式​实现​单​实例​。
     * ​静态​局部变量​只​在​当前​函数​内​有效​，​其他​函数​无法访问​。
     * ​静态​局部变量​只​在​第一次​被​调用​的​时候​初始化​，​也​存储​在​静态​存储​区​，​生命周期​从​第一次​被​初始化​起​至​程序​结束​止​。
     */
    static Single single;// C++11 ​保证​静态​局部变量​初始化​的​线程​安全​
    return single;
}

void Single::Print()
{
    std::cout &lt;&lt; "​我​的​实例​内存地址​是​:" &lt;&lt; this &lt;&lt; std::endl;
}
